'use strict';
// Weekly terms are the single calculation used by the calculator, ledger and documents.
const weeklyCredit=(capital,rate)=>Math.round(capital*rate)/100;
function weekStart(value){const date=new Date(value+'T12:00:00Z');if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==value)return null;date.setUTCDate(date.getUTCDate()-((date.getUTCDay()+6)%7));return date.toISOString().slice(0,10)}
if(demo.weeklyModelVersion!==1){if(demo.plan){demo.plan.period='week';demo.plan.status='active'}demo.companyShare=43;demo.weeklyModelVersion=1;demo.sessions??=[];demo.adjustments??=[];}
updateTariffMath=function(){const tier=demo.tariffs.find(t=>t.id===chosenTier);if(!tier||!$('#investment-amount'))return;investmentDraft=Number($('#investment-amount').value);const valid=Number.isFinite(investmentDraft)&&investmentDraft>=1&&investmentDraft<=1e7;$('#allocation-each').textContent=valid?money(investmentDraft/tier.count):'—';$('#allocation-payout').textContent=valid?money(weeklyCredit(investmentDraft,tier.rate)):'—';if($('#scenario-results'))$('#scenario-results').innerHTML=[1,4,12].map(weeks=>`<div><span>${weeks} ${weeks===1?'week':'weeks'}</span><strong>${valid?money(weeklyCredit(investmentDraft,tier.rate)*weeks):'—'}</strong><small>${(tier.rate*weeks).toFixed(1)}% of capital · no compounding</small></div>`).join('');$('#tariff-error').textContent=valid?'':'Enter an amount between $1 and $10,000,000.'};
sessionRows=function(){return demo.sessions.length?`<div class="table-scroll"><table><thead><tr><th>Event</th><th>Period starting</th><th>Capital</th><th>Rate</th><th>Credit</th><th>Record</th></tr></thead><tbody>${demo.sessions.slice().reverse().slice(0,30).map(s=>`<tr><td><strong>${s.period==='week'?'Weekly demo allocation':'Archived '+(s.period==='day'?'daily':'session')+' demo'}</strong><small>${escapeHtml(s.id)}</small></td><td>${escapeHtml(s.weekStart||s.day||s.date.slice(0,10))}</td><td>${money(s.capital??s.allocatedCapital??0)}</td><td>${s.rate.toFixed(1)}% / ${s.period==='week'?'week':s.period==='day'?'day':'session'}</td><td class="green-text">+${money(s.payout)}</td><td><button class="text-button credit-detail-button" data-credit-detail="${escapeHtml(s.id)}">View calculation →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No weekly allocations recorded yet. Your manager can record a sample week after the demo plan is active.</div>'};
actions['simulate-session']=()=>{if(role!=='admin'){actions.sessions();return}if(!demo.plan||demo.plan.status!=='active'){toast('Activate a demo client plan first.');return}const p=demo.plan;openModal(`<h2>Record a demo week</h2><p>Credit one weekly allocation to the client balance. Charging activity is the proposed revenue source; this is a sample calculation.</p><form id="weekly-credit-form"><label for="credit-week">A date in the week</label><input id="credit-week" type="date" value="${new Date().toISOString().slice(0,10)}" required><div class="allocation-math"><div><span>Invested demo capital</span><strong>${money(p.capital)}</strong></div><div><span>Weekly plan rate</span><strong>${p.rate.toFixed(1)}%</strong></div><div class="allocation-total"><span>Sample weekly credit</span><strong>${money(weeklyCredit(p.capital,p.rate))}</strong></div></div><p class="form-hint">A Monday–Sunday week can be credited once. No additional credit is created per vehicle.</p><div id="weekly-error" class="form-error" role="alert"></div><button class="button primary" type="submit">Record weekly demo credit</button></form>`)};
document.addEventListener('submit',e=>{if(e.target.id!=='weekly-credit-form')return;e.preventDefault();if(role!=='admin'||!demo.plan||demo.plan.status!=='active')return;const key=weekStart($('#credit-week').value);if(!key){$('#weekly-error').textContent='Choose a valid date.';return}if(demo.sessions.some(s=>s.period==='week'&&s.weekStart===key)){$('#weekly-error').textContent='This week already has an allocation. Choose another week.';return}const p=demo.plan,payout=weeklyCredit(p.capital,p.rate);demo.sessions.push({id:'WEEK-'+key,period:'week',weekStart:key,capital:p.capital,rate:p.rate,payout,stationIds:p.stationIds.slice(),planName:p.name,date:new Date().toISOString()});demo.balance=Math.round((demo.balance+payout)*100)/100;activity('Manager recorded sample week '+key+': +'+money(payout));persist();$('#modal').close();renderAdmin();toast('Weekly demo allocation recorded.')});
renderSessionWidget=function(){const card=$('.performance-card');let widget=$('#session-widget');if(!widget){card.querySelector('.card-heading').hidden=true;card.querySelector('.performance-body').hidden=true;widget=document.createElement('div');widget.id='session-widget';card.append(widget)}const p=demo.plan,capital=p?.capital||250,rate=p?.rate||demo.tariffs[0].rate;widget.innerHTML=`<div class="session-heading"><h2>Your weekly calculation</h2><span class="simulation-badge">DEMO</span></div><div class="engine-location">${p?escapeHtml(p.name)+' plan':'Example: Single plan'} <span>· ${p?.status==='active'?'Active demo allocation':'Illustration, not yet funded'}</span></div><div class="engine-flow"><button class="engine-node" data-action="tariffs"><span>${icon('assets')}</span><small>${money(capital)} invested</small></button><div class="engine-connector"><i></i></div><button class="engine-node" data-action="tariffs"><span>${rate.toFixed(1)}<em>%</em></span><small>Per week</small></button><div class="engine-connector"><i></i></div><button class="engine-node payout-node" data-action="engine-details"><span>${money(weeklyCredit(capital,rate))}</span><small>Weekly illustration</small></button></div><div class="engine-bottom"><span>Capital × weekly rate · no compounding</span><button data-action="engine-details">How it works ${icon('arrow')}</button></div>`};
actions['engine-details']=()=>{const p=demo.plan,capital=p?.capital||250,rate=p?.rate||demo.tariffs[0].rate;openModal(`<h2>How your participation works</h2><ol class="engine-explanation"><li><strong>Drivers pay for charging.</strong><span>These payments are the proposed source of company operating revenue.</span></li><li><strong>The company participates in the network.</strong><span>The demo assumes a 43% company ownership interest. This is separate from your plan rate.</span></li><li><strong>Your demo allocation is calculated weekly.</strong><span>${money(capital)} × ${rate.toFixed(1)}% = ${money(weeklyCredit(capital,rate))} per week. No extra payment is added for each car.</span></li></ol><div class="modal-note">Ownership documents and operating revenue have not been connected. Rates and allocations are illustrative, not verified returns.</div><button class="button primary" data-action="${role==='admin'?'simulate-session':'tariffs'}">${role==='admin'?'Record a demo week':'Review my plan'}</button>`)};
actions.sessions=()=>openModal(`<h2>Weekly allocation history</h2><p>Recorded sample allocations. Historical entries keep their original terms.</p>${sessionRows()}${role==='admin'?'<button class="button primary" data-action="simulate-session">Record a demo week</button>':''}`);
const contractBeforeWeekly=contractContent;
contractContent=function(){return contractBeforeWeekly().replaceAll('per completed session','per week on invested capital').replace('The displayed rate is applied to the capital allocated to the station.','The weekly rate is applied once to invested capital, without compounding or an extra per-vehicle credit.').replace('<h2>4. Reference stations','<h2>Company participation model</h2><p>The proposed model assumes a 43% company interest in a participating charging network. Network scope and ownership documentation are pending. This figure is not a verified share of the US market and is distinct from the client weekly rate.</p><h2>4. Reference stations')};
const planBarBeforeWeekly=renderPlanBar;
renderPlanBar=function(){planBarBeforeWeekly();const total=demo.sessions.filter(s=>s.period==='week').reduce((sum,s)=>sum+s.payout,0);$('.metrics-grid .metric-card:last-child>span').textContent='Weekly credits';$('.metrics-grid .metric-card:last-child>strong').textContent=money(total);$('.metrics-grid .metric-card:last-child>small').textContent='Recorded demo allocations';renderSessionWidget()};
renderSessionWidget();

// Inspect the values recorded at the time of the credit, not today's plan settings.
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-credit-detail]');if(!button)return;
 const s=demo.sessions.find(record=>record.id===button.dataset.creditDetail);if(!s)return;
 const isWeekly=s.period==='week',capital=s.capital??s.allocatedCapital??0;
 let period=s.weekStart||s.day||s.date.slice(0,10);
 if(isWeekly&&s.weekStart){const end=new Date(s.weekStart+'T12:00:00Z');if(Number.isFinite(end.getTime())){end.setUTCDate(end.getUTCDate()+6);period=s.weekStart+' – '+end.toISOString().slice(0,10);}}
 const expected=isWeekly?weeklyCredit(capital,s.rate):null;
 const recordedDate=new Date(s.date);
 const recordedAt=Number.isFinite(recordedDate.getTime())?new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'UTC',timeZoneName:'short'}).format(recordedDate):'Date unavailable';
 openModal(`<h2>${isWeekly?'Weekly credit details':'Archived demo credit'}</h2><p>Saved demo record. This entry is not a bank transfer or verified station revenue.</p><dl class="credit-record-details"><div><dt>Record</dt><dd>${escapeHtml(s.id)}</dd></div><div><dt>Period</dt><dd>${escapeHtml(period)}</dd></div><div><dt>Recorded at</dt><dd>${escapeHtml(recordedAt)}</dd></div><div><dt>Plan at recording</dt><dd>${escapeHtml(s.planName||'Not recorded')}</dd></div><div><dt>Capital at recording</dt><dd>${money(capital)}</dd></div><div><dt>Recorded rate</dt><dd>${Number(s.rate).toFixed(1)}% / ${isWeekly?'week':s.period==='day'?'day':'session'}</dd></div><div><dt>Actual demo credit</dt><dd>${money(s.payout)}</dd></div><div><dt>Reference stations</dt><dd>${s.stationIds?.length??'Not recorded'}</dd></div></dl>${isWeekly?`<div class="credit-record-calculation"><small>RECORDED CAPITAL × RECORDED WEEKLY RATE</small><strong>${money(capital)} × ${Number(s.rate).toFixed(1)}% = ${money(expected)}</strong><p>Rounded to cents. No compounding and no additional payment per charging vehicle.${Math.abs(expected-s.payout)>.005?' The saved credit differs from this formula; ask the demo manager to review the record.':''}</p></div>`:'<div class="modal-note">This archived entry retains its original period. It is not recalculated using the current weekly model.</div>'}<div class="trust-portal-links"><a href="how-it-works/#cash-flow">Understand the proposed revenue source ↗</a><a href="terms/">Access, fees & risks ↗</a></div><button class="button secondary" data-action="sessions">Back to allocation history</button>`);
});
